import { createRequire } from 'module';
import { WILAYAS } from './wilayas.js';

const require = createRequire(import.meta.url);

/** { [wilayaCode]: [[asciiName, arabicName], ...] } — generated by scripts/build-wilayas.mjs */
const COMMUNES = require('./communes.json');

/** Communes of a wilaya, looked up by official code or by name. Returns null for unknown wilayas. */
export const getCommunes = (codeOrName) => {
  const code = Number(codeOrName);
  const wilaya = Number.isInteger(code)
    ? WILAYAS.find((w) => w.code === code)
    : WILAYAS.find((w) => [w.name, w.ascii, w.arabic].some((n) => n.toLowerCase() === String(codeOrName).trim().toLowerCase()));
  if (!wilaya) return null;
  return {
    wilaya,
    communes: (COMMUNES[wilaya.code] || []).map(([name, arabic]) => ({ name, arabic })),
  };
};

export default COMMUNES;
